"""Post-process an autogenerated migration: custom column types -> plain SA types."""
import re, sys
p = sys.argv[1]
s = open(p, encoding="utf-8").read()
s = re.sub(r"app\.core\.security\.EncryptedString\(length=(\d+)\)", r"sa.String(length=\1)", s)
s = s.replace("    # ### commands auto generated by Alembic - please adjust! ###\n", "")
s = s.replace("    # ### end Alembic commands ###\n", "")
open(p, "w", encoding="utf-8").write(s)
